steps.solution:
variable "name" {
  type        = string
  description = "Name prefix for the security group"
}

variable "vpc_id" {
  type        = string
  description = "VPC to create the security group in"
}

variable "environment" {
  type        = string
  description = "Deployment environment"

  validation {
    condition     = contains(["dev", "staging", "prod"], var.environment)
    error_message = "environment must be dev, staging, or prod."
  }
}

variable "ingress_ports" {
  type        = list(number)
  description = "TCP ports to allow in"
  default     = [80, 443]
}

steps.starter_content:
resource "aws_security_group" "this" {
  name   = "web-sg"
  vpc_id = "vpc-0abc1234"

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["10.0.0.0/16"]
  }

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["10.0.0.0/16"]
  }
}

steps.hint:
dynamic "ingress" {
  for_each = var.ingress_ports
  content {
    from_port = ingress.value
    to_port   = ingress.value
    protocol  = "tcp"
    cidr_blocks = ["10.0.0.0/16"]
  }
}
Inside content, the current item is <block label>.value, here ingress.value. Delete both literal ingress blocks and the hardcoded vpc id.

steps.solution:
resource "aws_security_group" "this" {
  name   = "${var.name}-${var.environment}-sg"
  vpc_id = var.vpc_id

  dynamic "ingress" {
    for_each = var.ingress_ports
    content {
      from_port   = ingress.value
      to_port     = ingress.value
      protocol    = "tcp"
      cidr_blocks = ["10.0.0.0/16"]
    }
  }

  tags = {
    Environment = var.environment
  }
}

